/* Layout for this component's own nodes.
   These were per-node `styles` overrides. Past a certain number of them in
   one document the browser stops matching the compiled
   [data-bz-node="x"][data-bz-node] rules — some apply and some silently do
   not — so the same declarations live here instead, where they hold. See the
   note in the commit message; this is a platform bug worth fixing upstream.
   ------------------------------------------------------------------------- */
[data-bz-node="utility-bar"]{padding-left:48px;padding-right:48px}
[data-bz-node="utility-social-col"]{display:flex;align-items:center;gap:14px}
[data-bz-node="header"]{padding-top:18px;padding-bottom:26px;padding-left:48px;padding-right:48px;position:relative;overflow:visible}
[data-bz-node="header-nav-col"]{display:flex;align-items:center;justify-content:flex-end;gap:4px}
[data-bz-node="footer"]{padding-top:80px;padding-bottom:48px}
[data-bz-node="footer-main-row"]{display:grid;grid-template-columns:1.4fr 1fr 1fr 1fr;gap:40px;margin-bottom:60px}
[data-bz-node="footer-social-col"]{display:flex;align-items:center;gap:14px;margin-top:18px}
[data-bz-node="footer-credit-col"]{display:flex;align-items:baseline;justify-content:center;gap:8px}

/* ---------------------------------------------------------- UTILITY BAR ---
   Red strip: socials pinned left, quick links right, 10px tall padding. */

[data-bz-node="utility-bar"] { padding-block: 10px; }
[data-bz-node="utility-bar"] .bz-block { padding-block: 0; }
[data-bz-node="utility-social-col"] img,
[data-bz-node="footer-social-col"] img {
  width: 14px; height: 14px;
  /* Source icons are black SVGs, inverted to white rather than shipping a
     second set — the handoff's own decision, carried over. */
  filter: brightness(0) invert(1);
}
[data-bz-node="footer-social-col"] img { width: 16px; height: 16px; }
[data-bz-node="utility-social-col"] a,
[data-bz-node="footer-social-col"] a { display: flex; line-height: 1; }
[data-bz-node="utility-social-col"] a:hover,
[data-bz-node="footer-social-col"] a:hover { opacity: 0.7; }
[data-bz-node="utility-menu"] .bz-nav { gap: 22px; }
[data-bz-node="utility-menu"] .bz-navitem { font: 600 12px / 1.6 var(--font-body); }
[data-bz-node="utility-menu"] a { color: #fff; font: 600 12px / 1.6 var(--font-body); padding: 0; }
[data-bz-node="utility-menu"] a:hover { color: var(--ink); text-decoration: none; }

/* --------------------------------------------------------------- HEADER ---
   Dark bar, logo left at 64px, nav right, red phone button at the nav end.
   The mega panel is absolutely positioned and viewport-wide, so nothing in
   the header may clip overflow. */

[data-bz-node="header"] { border-bottom: 1px solid #333; overflow: visible; }
[data-bz-node="header"] .bz-block { padding-block: 0; }
[data-bz-node="header-logo"] { line-height: 0; }
[data-bz-node="header-logo"] a { display: flex; align-items: center; }
[data-bz-node="header-logo"] img { height: 64px; width: auto; display: block; }
[data-bz-node="header-menu"] .bz-nav { gap: 4px; row-gap: 6px; }
[data-bz-node="header-menu"] .bz-navitem > a,
[data-bz-node="header-menu"] .bz-navitem > button,
[data-bz-node="header-menu"] .bz-navitem > .bz-navlabel {
  display: inline-flex; align-items: center; gap: 4px;
  padding: 8px 10px;
  color: #EDEDED;
  font: 600 var(--text-small) / normal var(--font-body);
}
[data-bz-node="header-menu"] .bz-navitem > a:hover,
[data-bz-node="header-menu"] .bz-navitem > button:hover { color: var(--accent); text-decoration: none; }
[data-bz-node="header-menu"] .bz-nav > .bz-navitem--has-sub > .bz-navlabel::after {
  content: "\25BE";
  font-size: 10px;
}
[data-bz-node="header-menu"] [aria-current="page"] { color: var(--accent); font-weight: 700; }
[data-bz-node="header-phone"] { margin-left: 8px; }
[data-bz-node="header-phone"] .bz-btn { min-height: 0; padding: 11px 18px; font: 700 var(--text-small) / 1.6 var(--font-body); }

/* --------------------------------------------------------------- FOOTER ---
   Brand column wider than the three link columns; legal row rules off the
   grid above it; build credit centred under both. */

[data-bz-node="footer"] .bz-block { padding-block: 0; }
[data-bz-node="footer-logo"] img { height: 56px; width: auto; display: block; margin-bottom: 16px; }
[data-bz-node="footer-blurb"] { margin-bottom: 10px; }
[data-bz-node="footer-blurb"] p { font-size: 13px; line-height: 1.6; color: #A0A0A0; max-width: 260px; }
[data-bz-node="footer-mail"] p, [data-bz-node="footer-mail"] a { font: 400 13px / 1.6 var(--font-body); color: #A0A0A0; }
[data-bz-node="footer"] h4 {
  font: 700 var(--text-eyebrow) / 1 var(--font-body);
  letter-spacing: 0.1em;
  color: #8A8A8A;
  margin: 0 0 var(--space-5);
}
[data-bz-node="footer"] .bz-menu--vertical .bz-nav { gap: 10px; }
[data-bz-node="footer"] .bz-menu--vertical .bz-navitem { font: 400 var(--text-small) / 1.6 var(--font-body); }
[data-bz-node="footer"] .bz-menu--vertical a { padding: 0; color: #fff; font: 400 var(--text-small) / 1.6 var(--font-body); }
[data-bz-node="footer-legal-row"] { border-top: 1px solid #333; padding-top: var(--space-5); }
[data-bz-node="footer-legal-copy"] p { font-size: 12px; color: #8A8A8A; margin: 0; }
[data-bz-node="footer-legal-menu"] .bz-nav { gap: var(--space-5); }
[data-bz-node="footer-legal-menu"] .bz-navitem { font: 400 12px / 1.6 var(--font-body); }
[data-bz-node="footer-legal-menu"] a { padding: 0; font: 400 12px / 1.6 var(--font-body); color: #8A8A8A; }
[data-bz-node="footer-credit-row"] { margin-top: var(--space-6); }
[data-bz-node="footer-credit-text"] p { font-size: 12px; color: #8A8A8A; margin: 0; }
[data-bz-node="footer-credit-logo"] img { height: 22px; width: auto; position: relative; top: 4px; }

@media (max-width: 640px) {
  [data-bz-node="footer-main-row"] { grid-template-columns: 1fr; gap: 36px; }
}

/* --------------------------------------------------------------- PHONE ---
   The handoff's two breakpoints. Below 640px the utility bar keeps only the
   socials, and the header collapses to logo + phone + hamburger on one line. */

@media (max-width: 640px) {
  [data-bz-node="utility-bar"] { padding-inline: 20px; }
  [data-bz-node="utility-row"] { display: flex; justify-content: center; }
  [data-bz-node="utility-links-col"] { display: none; }
  [data-bz-node="utility-social-col"] { justify-content: center; }

  [data-bz-node="header"] { padding: 14px 16px; }
  [data-bz-node="header-row"] { display: flex; align-items: center; gap: 12px; }
  [data-bz-node="header-logo-col"] { flex: 0 0 auto; }
  [data-bz-node="header-logo"] img { height: 40px; }
  [data-bz-node="header-nav-col"] { flex: 1 1 auto; justify-content: flex-end; gap: 8px; }
  [data-bz-node="header-phone"] { margin-left: 0; order: 1; }
  [data-bz-node="header-phone"] .bz-btn { padding: 0 12px; height: 40px; font-size: var(--text-xs, 13px); }
  [data-bz-node="header-menu"] { order: 2; }
}

/* The renderer's collapsed-menu button draws its bars in currentColor, which
   on the dark header has to be the chrome text colour. */
[data-bz-node="header-menu"] .bz-menu-toggle { color: #EDEDED; border-color: #333; }
